importScripts('./vendor/mediapipe/vision_bundle.js');
const {FilesetResolver,ImageSegmenter}=Vision;
let segmenter;
self.onmessage=async({data})=>{try{if(data.type==='init'){const root=new URL('./',self.location.href);const vision=await FilesetResolver.forVisionTasks(new URL('vendor/mediapipe/wasm',root).href);segmenter=await ImageSegmenter.createFromOptions(vision,{baseOptions:{modelAssetPath:new URL('vendor/models/selfie_segmenter.tflite',root).href,delegate:'CPU'},canvas:new OffscreenCanvas(1,1),runningMode:'IMAGE',outputCategoryMask:false,outputConfidenceMasks:true});postMessage({type:'ready'});return;}if(data.type==='segment'){try{segmenter.segment(data.bitmap,result=>{const masks=result.confidenceMasks;if(!masks?.length)throw Error('인물 마스크를 만들 수 없어요.');const labels=segmenter.getLabels().map(x=>x.toLowerCase());const index=masks.length===1?0:Math.max(0,labels.findIndex(x=>/person|human|foreground/.test(x))>=0?labels.findIndex(x=>/person|human|foreground/.test(x)):1);const m=masks[index],values=new Float32Array(m.getAsFloat32Array());postMessage({type:'result',id:data.id,mask:values.buffer,width:m.width,height:m.height},[values.buffer]);});}finally{data.bitmap.close();}}}catch(e){postMessage({type:'error',id:data.id,message:e.message||'인물 분할을 준비할 수 없어요.'});}};
